parameters.jsCode:
// 1. Получаем данные из Webhook (безопасный синтаксис n8n)
const webhookData = $input.all()[0]?.json?.body || {};
const roleId = webhookData.role_id ?? "logistics_lead";
const teamMetrics = webhookData.team_metrics;

// 2. Наша "База данных" заранее заготовленных вакансий (JD)
const jobDescriptions = {
  "logistics_lead": {
    "title": "Senior Lead, Production & Logistics Excellence",
    "core_requirements": ["Lean Manufacturing", "Supply Chain Management", "Crisis Management", "Cross-functional Leadership"]
  },
  "ev_tech_director": {
    "title": "Director of EV Software Integration",
    "core_requirements": ["Software Engineering", "Agile Scaling", "EV Battery Systems", "Rapid Prototyping"]
  }
};

// 3. Наша база кандидатов (твои 4 кандидата из прошлых шагов)
const candidates = [
  { "name": "Alexander Neumann", "skills": ["Lean Manufacturing", "Quality Control"], "background": "Automotive Continuity" },
  { "name": "Elena Marcus", "skills": ["Digital Transformation", "Agile Scaling"], "background": "Amazon Experience" },
  { "name": "Victor Gross", "skills": ["Crisis Management", "Risk Assessment"], "background": "Turnaround" },
  { "name": "Sarah Lee", "skills": ["Software Engineering", "EV Battery Systems"], "background": "Startup / EV Tech" }
];

// 4. Собираем всё в один идеальный пакет для AI-Агента
return [
  {
    "json": {
      "task": "Evaluate candidates across 3 scenarios simultaneously",
      "selected_jd": jobDescriptions[roleId],
      "current_team_metrics": teamMetrics,
      "candidate_pool": candidates
    }
  }
];
